<?php
namespace Modules\Ran\Reports;
class SupplierDueReport extends AbstractRanReport{public function title():string{return 'Supplier Outstanding';}public function headings():array{return ['Supplier ID','Supplier','Mobile','Purchase Count','Total','Paid','Balance'];}public function rows(array $f):array{$q=\DB::table('ran_purchases as p')->leftJoin('contacts as c','c.id','=','p.supplier_contact_id')->whereNull('p.deleted_at')->where('p.balance_amount','>',0)->where('p.business_id',\Modules\Ran\Support\RanContext::businessId());if(!empty($f['location_id']))$q->where('p.location_id',$f['location_id']);return $q->groupBy('p.supplier_contact_id','c.name','c.supplier_business_name','c.mobile')->get(['p.supplier_contact_id',\DB::raw('COALESCE(c.supplier_business_name,c.name) supplier'),'c.mobile',\DB::raw('COUNT(*) purchase_count'),\DB::raw('SUM(p.total_amount) total'),\DB::raw('SUM(p.paid_amount) paid'),\DB::raw('SUM(p.balance_amount) balance')])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Total'=>array_sum(array_column($rows,'total')),'Paid'=>array_sum(array_column($rows,'paid')),'Balance'=>array_sum(array_column($rows,'balance'))];}}
